import json
import datetime


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def event_fields(provider, raw):
    # M365 (Graph) and Google Calendar shape their events differently —
    # Graph: subject, nested start.dateTime/end.dateTime. Google: summary,
    # nested start.dateTime (or start.date for all-day), same for end.
    if provider == "outlook":
        start = ((raw.get("start") or {}).get("dateTime") or "")
        end = ((raw.get("end") or {}).get("dateTime") or "")
        subject = raw.get("subject") or ""
    else:
        start = ((raw.get("start") or {}).get("dateTime") or (raw.get("start") or {}).get("date") or "")
        end = ((raw.get("end") or {}).get("dateTime") or (raw.get("end") or {}).get("date") or "")
        subject = raw.get("summary") or ""
    return str(raw.get("id") or ""), subject, start, end


now = datetime.datetime.utcnow()
window_start = now.strftime("%Y-%m-%dT%H:%M:%SZ")
window_end = (now + datetime.timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")

practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    slug = str(fname)[:-5]
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice:
        practices.append({"slug": slug, "practice": practice})

# Detection is deliberately weaker than a true change feed: it diffs each
# event's own (start, end) against the last snapshot, not a modification
# timestamp — neither calendar tool here returns one. A subject- or
# location-only edit with the same times won't be caught.
changed_items = []
for p in practices:
    provider = str(p["practice"].get("email_provider") or "outlook")
    snapshot = read_json("PracticeManager/CalendarSnapshot/" + p["slug"] + ".json", {}) or {}

    raw_events = []
    try:
        if provider == "outlook":
            result = api.connectors.invoke(
                server="m365-calendar", tool="list_events",
                args={"startDateTime": window_start, "endDateTime": window_end, "limit": 50},
            )
            raw_events = result if isinstance(result, list) else (result or {}).get("value") or []
        else:
            result = api.connectors.invoke(
                server="google-workspace-calendar", tool="list_events",
                args={"timeMin": window_start, "timeMax": window_end, "maxResults": 50, "singleEvents": True, "orderBy": "startTime"},
            )
            raw_events = (result or {}).get("items") or []
    except Exception:
        raw_events = []

    for raw in raw_events:
        event_id, subject, start, end = event_fields(provider, raw if isinstance(raw, dict) else {})
        if not (event_id and start and end):
            continue
        prior = snapshot.get(event_id) or {}
        if prior.get("start") == start and prior.get("end") == end:
            continue
        changed_items.append({
            "slug": p["slug"],
            "practice": p["practice"],
            "event_id": event_id,
            "subject": subject,
            "start": start,
            "end": end,
            "prior_block_id": prior.get("cliniko_block_id") or "",
        })

import json
import re
import datetime

AI_PROMPT = (
    "You are drafting a short, warm message on behalf of a healthcare clinic to a patient whose booked "
    "appointment now clashes with the practitioner's own calendar. Apologise briefly, explain a reschedule "
    "is needed, and offer the times given. Never give clinical advice, diagnosis or interpretation. Keep it "
    "under 120 words."
)
AI_HINT = '{"subject": "", "body": ""}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def practice_today(settings):
    tz_name = (settings or {}).get("timezone") or "UTC"
    try:
        from zoneinfo import ZoneInfo
        return datetime.datetime.now(ZoneInfo(tz_name)).date()
    except Exception:
        return datetime.datetime.now(datetime.timezone.utc).date()


item = params.get("item") or {}
slug = item.get("slug") or ""
practice = item.get("practice") or {}
event_id = item.get("event_id") or ""
subject = item.get("subject") or "Calendar event"
start = item.get("start") or ""
end = item.get("end") or ""
outcome = "skipped"
alerts_raised = 0

business_id = str(practice.get("cliniko_business_id") or "")

if slug and event_id and start and end and business_id:
    try:
        prac_result = api.connectors.invoke(
            server="cliniko-practice", tool="list_practitioners", args={"business_id": business_id},
        )
        practitioners = prac_result if isinstance(prac_result, list) else (prac_result or {}).get("practitioners") or []
    except Exception:
        practitioners = []
    # Sole-practitioner clinics (this plugin's whole premise) have exactly one
    # active practitioner per business — take the first rather than asking
    # the practice to store an id nowhere else in its settings file.
    practitioner_id = str((practitioners[0] or {}).get("id") or "") if practitioners else ""

    if not practitioner_id:
        outcome = "skipped_no_practitioner"
    else:
        block_id = item.get("prior_block_id") or ""
        note = "Synced from calendar: " + subject
        try:
            if block_id:
                api.connectors.invoke(
                    server="cliniko-scheduling", tool="update_unavailable_block",
                    args={"id": block_id, "patch": {"starts_at": start, "ends_at": end, "notes": note}},
                )
            else:
                created = api.connectors.invoke(
                    server="cliniko-scheduling", tool="create_unavailable_block",
                    args={"block": {"business_id": business_id, "practitioner_id": practitioner_id, "starts_at": start, "ends_at": end, "notes": note}},
                )
                block_id = str((created or {}).get("id") or "")
        except Exception:
            pass

        snapshot = read_json("PracticeManager/CalendarSnapshot/" + slug + ".json", {}) or {}
        snapshot[event_id] = {"start": start, "end": end, "subject": subject, "cliniko_block_id": block_id}
        write_json("PracticeManager/CalendarSnapshot/" + slug + ".json", snapshot)

        clashes = []
        try:
            result = api.connectors.invoke(
                server="cliniko-scheduling", tool="list_individual_appointments",
                args={
                    "q": [
                        "business_id:=" + business_id,
                        "practitioner_id:=" + practitioner_id,
                        "starts_at:<" + end,
                        "ends_at:>" + start,
                    ],
                    "per_page": 50,
                },
            )
            rows = (result or {}).get("individual_appointments") or []
            clashes = [r for r in rows if not r.get("cancelled_at")]
        except Exception:
            clashes = []

        policy = practice.get("policy") or {}
        tone = policy.get("tone") or "warm, concise, no jargon"
        reviewer = practice.get("reviewer_id") or ""

        for clash in clashes:
            patient_id = extract_id(clash.get("patient"))
            patient_name = clash.get("patient_name") or "this patient"
            appt_type_id = extract_id(clash.get("appointment_type"))

            slots = []
            if appt_type_id:
                try:
                    today = practice_today(practice)
                    avail = api.connectors.invoke(
                        server="cliniko-scheduling", tool="get_available_times",
                        args={"business_id": business_id, "practitioner_id": practitioner_id, "appointment_type_id": appt_type_id, "from_time": today.isoformat(), "to_time": (today + datetime.timedelta(days=6)).isoformat()},
                    )
                    raw_slots = avail if isinstance(avail, list) else (avail or {}).get("available_times") or []
                    for s in raw_slots[:3]:
                        t = s.get("appointment_start") if isinstance(s, dict) else s
                        if t:
                            slots.append(str(t))
                except Exception:
                    slots = []

            email = ""
            if patient_id:
                try:
                    patient = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id})
                    email = (patient or {}).get("email") or ""
                except Exception:
                    email = ""

            try:
                drafted = api.ai.extract(
                    prompt=AI_PROMPT,
                    input=json.dumps({
                        "patient_name": patient_name,
                        "clashing_appointment_time": clash.get("starts_at") or "",
                        "available_times": slots,
                        "tone": tone,
                    }),
                    schema_hint=AI_HINT,
                )
            except Exception:
                drafted = {}
            drafted = drafted if isinstance(drafted, dict) else {}
            draft_subject = drafted.get("subject") or "We need to reschedule"
            draft_body = drafted.get("body") or (
                "Hi " + patient_name + ", the practitioner's calendar has changed and your booked appointment "
                "now clashes. Please reply or call us to find a new time."
            )

            description = (
                "**Patient:** " + patient_name + "  \n"
                "**Clashing booking:** " + str(clash.get("starts_at") or "") + "  \n"
                "**Caused by calendar event:** " + subject + " (" + start + " to " + end + ")  \n\n"
                "**Drafted subject:** " + draft_subject + "  \n\n"
                "**Drafted message:**\n\n" + draft_body
            )
            if not email:
                description += "\n\n_No email on file for this patient — \"Send as drafted\" won't be able to send._"

            workq_item = api.workq.create(
                title="Calendar clash: " + patient_name,
                scope="org",
                description=description,
                priority="high",
                assignee_ids=[reviewer] if reviewer else None,
                labels=["healthcare-practice-management", "calendar-guard"],
            )
            workq_id = workq_item["id"]
            api.workq.attach_form(todo_id=workq_id, form_id=params["approval_form"])

            write_json("PracticeManager/NoShowDrafts/" + workq_id + ".json", {
                "slug": slug,
                "appointment_id": str(clash.get("id") or ""),
                "patient_id": patient_id,
                "patient_name": patient_name,
                "email": email,
                "subject": draft_subject,
                "body": draft_body,
            })
            alerts_raised += 1

        outcome = "synced"
